from google.cloud import documentai_v1beta3 as documentai
from google.api_core.client_options import ClientOptions

def validate_document_fields(payload, config=None):
    config = config or {}
    project_id = config.get("project_id", os.environ.get("GOOGLE_CLOUD_PROJECT"))
    location = config.get("location", "us")
    processor_id = config.get("processor_id")

    if not all([project_id, location, processor_id]):
        raise ValueError("Missing project_id, location, or processor_id in config or environment.")

    document_bytes = payload.get("document_bytes")
    mime_type = payload.get("mime_type", "application/pdf")

    if not document_bytes:
        raise ValueError("Payload must contain 'document_bytes' with the document content.")

    opts = ClientOptions(api_endpoint=f"{location}-documentai.googleapis.com")
    client = documentai.DocumentProcessorServiceClient(client_options=opts)

    processor_name = client.processor_path(project_id, location, processor_id)

    raw_document = documentai.RawDocument(
        content=document_bytes,
        mime_type=mime_type,
    )

    request = documentai.ProcessRequest(
        name=processor_name,
        raw_document=raw_document,
    )

    response = client.process_document(request=request)
    document = response.document

    extracted_fields = {}
    if document.entities:
        for entity in document.entities:
            field_name = entity.type_
            field_value = None

            # Prioritize normalized_value for structured data types
            if entity.normalized_value and entity.normalized_value.text:
                field_value = entity.normalized_value.text
            # Fallback to text_anchor from the document text
            elif entity.text_anchor and document.text and entity.text_anchor.text_segments:
                # Concatenate text from all segments for the field value
                segment_texts = []
                for segment in entity.text_anchor.text_segments:
                    if segment.start_index is not None and segment.end_index is not None:
                        segment_texts.append(document.text[segment.start_index:segment.end_index])
                field_value = "".join(segment_texts)
            # Fallback to direct text_content if available
            elif entity.text_content:
                field_value = entity.text_content

            extracted_fields[field_name] = {
                "value": field_value,
                "confidence": entity.confidence
            }
    return extracted_fields
